Throughout this work, $X$ is a real Hilbert space with inner product $\scal{\cdot}{\cdot}$ and induced norm $\|\cdot\|$. 
The set of nonnegative integers is denoted by $\NN$, the set of real numbers by $\RR$, the set of nonnegative real numbers by $\RP := \menge{x \in \RR}{x \geq 0}$, and the set of the positive real numbers by $\RPP := \menge{x \in \RR}{x >0}$.
We use the notation $A\colon X\rightrightarrows X$ to indicate that $A$ is a set-valued operator on $X$ and the notation $A\colon X\to X$ to indicate that $A$ is a single-valued operator on $X$. 

Let $A$ be an operator on $X$. The \emph{domain} of $A$ is $\dom A :=\menge{x\in X}{Ax\neq \varnothing}$, the \emph{graph} of $A$ is $\gra A :=\menge{(x,u)\in X\times X}{u\in Ax}$, and the set of \emph{fixed points} of $A$ is $\Fix A :=\menge{x\in X}{x\in Ax}$. The \emph{inverse} of $A$, denoted by $A^{-1}$, is the operator with graph $\gra A^{-1} :=\menge{(u,x)\in X\times X}{u\in Ax}$.
We say that $A$ is \emph{Lipschitz continuous} with constant $\ell\in \RP$ if it is single-valued and
\begin{equation}
\forall x, y\in \dom A,\quad \|Ax-Ay\|\leq \ell\|x-y\|.
\end{equation}
The operator $A$ is \emph{nonexpansive} if it is Lipschitz continuous with constant $1$, i.e.,
\begin{equation}
\forall x, y\in \dom A,\quad \|Ax-Ay\|\leq \|x-y\|.
\end{equation}
An operator $A\colon X\rightrightarrows X$ is said to be \emph{monotone} if
\begin{equation}
\forall (x, u), (y, v)\in \gra A,\quad \scal{x-y}{u-v}\geq 0,
\end{equation}
and said to be \emph{maximally monotone} if it is monotone and there exists no monotone operator $B\colon X\rightrightarrows X$ such that $\gra B$ properly contains $\gra A$. The \emph{resolvent} of $A\colon X\rightrightarrows X$ is defined by
\begin{equation}
J_A:= (\Id+ A)^{-1},
\end{equation}
where $\Id$ is the identity operator. The \emph{relaxed resolvent} of $A$ with parameter $\lambda\in\RP$ is defined by
\begin{equation}
J_A^\lambda:= (1-\lambda)\Id+ \lambda J_A.
\end{equation}


\begin{definition}[$\alpha$-monotonicity]
\label{d:alpha_mono}
An operator $A\colon X\rightrightarrows X$ is said to be \emph{$\alpha$-monotone} ($\alpha\in \RR$) if
\begin{equation}
\label{e:alpha-mono}
\forall (x,u), (y,v)\in \gra A,\quad \scal{x-y}{u-v}\geq \alpha\|x-y\|^2.
\end{equation}
The constant $\alpha$ is referred to as the \emph{monotonicity constant}.
We also say that $A$ is \emph{maximally $\alpha$-monotone} if it is $\alpha$-monotone and there is no $\alpha$-monotone operator whose graph strictly contains $\gra A$.  
\end{definition}

We note that $0$-monotonicity simply means monotonicity, that if $\alpha>0$, then $\alpha$-monotonicity is precisely the notion of \emph{strong monotonicity} \cite[Definition~22.1(iv)]{BC17}, and that if $\alpha<0$, then $\alpha$-monotonicity can be referred to as \emph{weak monotonicity}.


\begin{remark}[Lipschitz $\alpha$-monotone operators]
\label{r:Lip_mono}
Suppose that $A$ is Lipschitz continuous with constant $\ell$. Then $A$ is single-valued and 
\begin{equation}
\forall x,y\in\dom A,\quad
|\scal{x-y}{Ax-Ay}|\leq \|x-y\|\cdot\|Ax-Ay\|\leq \ell\|x-y\|^2,
\end{equation}
which yields
\begin{equation}
\label{e:L-inequality}
\forall x,y\in\dom A,\quad -\ell\|x-y\|^2\leq \scal{x-y}{Ax-Ay}\leq \ell\|x-y\|^2.
\end{equation}
We immediately deduce that $A$ is $(-\ell)$-monotone. Now suppose, in addition, that $A$ is $\alpha$-monotone. On the one hand, we can always assume without loss of generality that $\alpha\geq-\ell$. On the other hand, it follows from the $\alpha$-monotonicity and \eqref{e:L-inequality} that $\alpha\leq \ell$ as soon as $\dom A$ has more than one element. Therefore, unless otherwise stated, whenever $A$ is both $\alpha$-monotone and Lipschitz continuous with constant $\ell$, we assume that $|\alpha|\leq\ell$.
\end{remark}

Throughout this section, $A,B\colon X\rightrightarrows X$, $(\gamma,\delta,\lambda,\mu)\in \RPP^4$, and $\kappa\in \left]0,1\right[$. We define
\begin{subequations}\label{e:JRT}
\begin{align}
J_1&:=J_{\gamma A}=(\Id+\gamma A)^{-1}, 
&R_1&:=J_{\gamma A}^\lambda=(1-\lambda)\Id+\lambda J_1,\\
J_2&:=J_{\delta B}=(\Id+\delta B)^{-1},
&R_2&:=J_{\delta B}^\mu=(1-\mu)\Id+\mu J_2
\end{align}
and consider the \emph{adaptive DR operator} defined by
\begin{align}\label{e:aDR}
T:= (1-\kappa)\Id+ \kappa R_2R_1.
\end{align}
\end{subequations}  


The adaptive DR operator is indeed motivated by the problem of finding a zero of the sum of two operators, that is,
\begin{equation}\label{e:sumprob}
\text{find $x\in X$ such that}\quad 0\in Ax+Bx.
\end{equation}
We also denote by
\begin{equation}
\zer(A+B) :=(A+B)^{-1}(0) =\menge{x\in X}{0\in Ax+Bx}
\end{equation}
the set of solutions of problem \eqref{e:sumprob}. Given a starting point $x_0\in X$, the \emph{adaptive DR algorithm} generates a sequence $(x_n)_\nnn$, also called a \emph{DR sequence}, by 
\begin{equation}\label{e:dr_seq}
\forall\nnn,\quad x_{n+1}\in Tx_n.
\end{equation}


Recall that a sequence $(x_n)_\nnn$ converges to $\overline{x}$ with \emph{$Q$-linear} (or simply \emph{linear}) rate $\rho\in\left[0,1\right[$ if
\begin{equation}
\forall\nnn,\quad \|x_{n+1}-\overline{x}\|\leq \rho\|x_n-\overline{x}\|.
\end{equation}

