\begin{fact}
\label{f:Minty}
Let $A\colon X\rightrightarrows X$ be monotone and let $\gamma\in \RPP$. Then $\dom J_{\gamma A} =X$ if and only if $A$ is maximally monotone.
\end{fact}

\begin{proof}
By definition, $\dom J_{\gamma A} =\ran(\Id+\gamma A) :=(\Id+\gamma A)(X)$. Since $\gamma\in \RPP$, it holds that $\gamma A$ is monotone. According to Minty's theorem (see, e.g., \cite[Theorem~21.1]{BC17}), $\dom J_{\gamma A} =\ran(\Id+\gamma A) =X$ if and only if $\gamma A$ is maximally monotone. By \cite[Proposition~20.22]{BC17}, the latter occurs if and only if $A$ is maximally monotone. 
\end{proof}

\begin{lemma}[monotonicity versus $\alpha$-monotonicity]
\label{l:transfer}
Let $A\colon X\rightrightarrows X$ and let $\alpha, \beta\in \RR$. Then the following hold:
\begin{enumerate}
\item\label{l:transfer_mono} 
$A$ is $\alpha$-monotone if and only if $A-\beta\Id$ is $(\alpha-\beta)$-monotone.
\item\label{l:transfer_maxmono}
$A$ is maximally $\alpha$-monotone if and only if $A-\beta\Id$ is maximally $(\alpha-\beta)$-monotone. 
\end{enumerate}
Consequently, $A$ is (resp., maximally) $\alpha$-monotone if and only if $A-\alpha\Id$ is (resp., maximally) monotone.
\end{lemma}

\begin{proof}
\ref{l:transfer_mono}: We first have the equivalences
\begin{subequations}
\begin{align}
(x,u)\in \gra A &\iff (x,u-\beta x)\in \gra(A-\beta\Id), \\
(y,v)\in \gra A &\iff (y,v-\beta y)\in \gra(A-\beta\Id),
\end{align}
\end{subequations}
and
\begin{equation}
\scal{x-y}{u-v}\geq \alpha\|x-y\|^2 \iff \scal{x-y}{(u-\beta x)-(v-\beta y)}\geq (\alpha-\beta)\|x-y\|^2,
\end{equation}
from which the conclusion follows.

\ref{l:transfer_maxmono}: Assume that $A$ is maximally $\alpha$-monotone. By \ref{l:transfer_mono}, $A-\beta\Id$ is $(\alpha-\beta)$-monotone. Now, suppose that $A-\beta\Id$ is not maximally $(\alpha-\beta)$-monotone. Then there must exist $B'\colon X\rightrightarrows X$ such that $B'$ is $(\alpha-\beta)$-monotone and $\gra(A-\beta\Id)\subsetneq \gra B'$. It follows that $B :=B'+\beta\Id$ is $\alpha$-monotone due to \ref{l:transfer_mono} and that $\gra A\subsetneq \gra B$, which contradict the maximal $\alpha$-monotonicity of $A$. We deduce that if $A$ is maximally $\alpha$-monotone, then $A-\beta\Id$ is maximally $(\alpha-\beta)$-monotone. This also implies that if $A-\beta\Id$ is maximally $(\alpha-\beta)$-monotone, then $A =(A-\beta\Id)+\beta\Id$ is maximally $\alpha$-monotone, and we are done. 
\end{proof}

\begin{lemma}[resolvents of $\alpha$-monotone operators]
\label{l:resol}
Let $A\colon X\rightrightarrows X$ be $\alpha$-monotone and let $\gamma\in \RPP$. Then the following hold:
\begin{enumerate}
\item\label{l:resol_gen}
For all $(x,a), (y,b)\in \gra J_{\gamma A}$,
\begin{subequations}
\begin{align}
\label{e:resol_gen}
\scal{x-y}{a-b} &\geq (1+\gamma\alpha)\|a-b\|^2 \quad\text{and}\\
\|x-y\| &\geq (1+\gamma\alpha)\|a-b\|.
\end{align} 
\end{subequations}
\item\label{l:resol_single}
If $J_{\gamma A}$ is single-valued, then, for all $x,y\in \dom J_{\gamma A}$,
\begin{equation}
\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq (1+\gamma\alpha)\|J_{\gamma A}x-J_{\gamma A}y\|^2,
\end{equation}
i.e., $J_{\gamma A}$ is $(1+\gamma\alpha)$-cocoercive.
\end{enumerate}
\end{lemma}

\begin{proof}
\ref{l:resol_gen}: Let $(x,a), (y,b)\in \gra J_{\gamma A}$. Then $x\in (\Id+\gamma A)a$, $y\in (\Id+\gamma A)b$, and so $x =a+\gamma u$, $y =b+\gamma v$ for some $u\in Aa$, $v\in Ab$. We derive from the $\alpha$-monotonicity of $A$ that 
\begin{subequations}
\begin{align}
\scal{x-y}{a-b}
&=\scal{(a+\gamma u)-(b+\gamma v)}{a-b}\\
&=\|a-b\|^2+\gamma\scal{a-b}{u-v}\\
&\geq \|a-b\|^2+\gamma\alpha\|a-b\|^2\\
&=(1+\gamma\alpha)\|a-b\|^2.
\end{align}
\end{subequations}
Now, by the Cauchy--Schwarz inequality,
\begin{equation}
\|x-y\|\|a-b\|\geq \scal{x-y}{a-b}\geq (1+\gamma\alpha)\|a-b\|^2.
\end{equation}
which gives $\|x-y\|\geq (1+\gamma\alpha)\|a-b\|$ while noting that this is trivial when $a =b$. 

\ref{l:resol_single}: This is a direct consequence of \ref{l:resol_gen}.
\end{proof}

\begin{proposition}[single-valuedness and full domain]
\label{p:resol}
Let $A\colon X\rightrightarrows X$ be $\alpha$-monotone and let $\gamma\in \RPP$ such that $1+\gamma\alpha >0$. Then the following hold:
\begin{enumerate}
\item\label{p:resol_single} 
$J_{\gamma A}$ is single-valued.
\item\label{p:resol_dom} 
$\dom J_{\gamma A} =X$ if and only if $A$ is maximally $\alpha$-monotone.
\end{enumerate}
\end{proposition}

\begin{proof}
\ref{p:resol_single}: This follows from Lemma~\ref{l:resol}\ref{l:resol_gen}.

\ref{p:resol_dom}: By Lemma~\ref{l:transfer}\ref{l:transfer_mono}, $A':=A-\alpha\Id$ is monotone.
Noting that $(\beta T)^{-1} =T^{-1}\circ \frac{1}{\beta}\Id$ for any operator $T$ and any $\beta\in \RR\smallsetminus\{0\}$, we have
\begin{subequations}
\begin{align}
J_{\gamma A}&=(\Id+\gamma A)^{-1}=\big((1+\gamma\alpha)\Id+\gamma(A-\alpha\Id)\big)^{-1}\\
&=\left(\Id+\frac{\gamma}{1+\gamma\alpha} A'\right)^{-1} \circ \left(\frac{1}{1+\gamma\alpha}\Id\right)\\
&=J_{\frac{\gamma}{1+\gamma\alpha}A'}\circ \left(\frac{1}{1+\gamma\alpha}\Id\right).
\end{align}
\end{subequations}
It follows that 
\begin{subequations}
\begin{align}
\dom J_{\gamma A} =X & \iff \dom J_{\frac{\gamma}{1+\gamma\alpha}A'} =X &&\\
& \iff \text{$A'$ is maximally monotone} &&\hspace*{-.8in}\text{(by Fact~\ref{f:Minty})} \\
& \iff \text{$A$ is maximally $\alpha$-monotone} &&\hspace*{-.8in}\text{(by Lemma~\ref{l:transfer}\ref{l:transfer_maxmono})}.
\end{align}
\end{subequations}
The proof is complete.
\end{proof}

\begin{proposition}[maximal $\alpha$-monotonicity]
\label{p:maxalpha}
The following statements hold: 
\begin{enumerate}
\item\label{p:maxalpha_mono} 
Let $A\colon X\rightrightarrows X$ and $\alpha\in \RP$. Then $A$ is maximally $\alpha$-monotone if and only if $A$ is $\alpha$-monotone and maximally monotone.
\item\label{p:maxalpha_cont} 
Let $A\colon X\to X$ and $\alpha\in \RR$. Then $A$ is maximally $\alpha$-monotone if $A$ is $\alpha$-monotone and continuous with full domain.
\end{enumerate}
\end{proposition}

\begin{proof}
\ref{p:maxalpha_mono}: Since $\alpha\geq 0$, it follows from Fact~\ref{f:Minty} that $A$ is $\alpha$-monotone and maximally monotone if and only if $A$ is $\alpha$-monotone and $\dom J_A =X$, which, by Proposition~\ref{p:resol}\ref{p:resol_dom}, happen if and only if $A$ is maximally $\alpha$-monotone.

\ref{p:maxalpha_cont}: Set $A' :=A-\alpha\Id$. Then $A'$ is monotone (due to Lemma~\ref{l:transfer}\ref{l:transfer_mono}) and continuous with full domain. By \cite[Corollary~20.28]{BC17}, $A'$ is maximally monotone, and by Lemma~\ref{l:transfer}\ref{l:transfer_maxmono}, $A$ is maximally $\alpha$-monotone. 
\end{proof}

\begin{lemma}[resolvents of Lipschitz $\alpha$-monotone operators]
\label{l:L-resol}
Let $A\colon X\to X$ be Lipschitz continuous with constant $\ell$ and let $\gamma\in \RPP$. Then the following hold:
\begin{enumerate}
\item\label{l:L-resol_only} 
For all $(x,a), (y,b)\in \gra J_{\gamma A}$,
\begin{subequations}
\begin{align}
\label{e:expan}
\|a-b\|&\geq \frac{1}{1+\gamma\ell}\|x-y\|,\\
\label{e:L-resol_only}
\scal{x-y}{a-b}&\geq \frac{1}{2}\|x-y\|^2 +\frac{1}{2}(1-\gamma^2\ell^2)\|a-b\|^2,
\end{align}
\end{subequations}
and if $\gamma\ell\leq 1$, then
\begin{equation}\label{e:L-resol_only1}
\scal{x-y}{a-b}\geq \frac{1}{1+\gamma\ell}\|x-y\|^2.
\end{equation}
\item\label{l:L-resol_mono}
If $A$ is $\alpha$-monotone with $1+\gamma\alpha >0$, then, for all $x, y\in \dom J_{\gamma A}$, 
\begin{equation}
\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq (1+\gamma\alpha)\alpha_J\|x-y\|^2,
\end{equation}
where 
\begin{subequations}
\label{e:alpha_J}
\begin{equation}
\alpha_J 
:=\begin{cases}
\dfrac{1}{1+2\gamma\alpha+\gamma^2\ell^2} &\text{if~} \gamma\ell\geq 1 
,\\
\dfrac{1}{(1+\gamma\alpha)(1+\gamma\ell)} &\text{if~} \gamma\ell\leq 1;
\end{cases}
\end{equation}
and if additionally $A$ satisfies \eqref{e:alpha-mono} with equality, then 
\begin{equation}
\alpha_J :=\frac{1}{1+2\gamma\alpha+\gamma^2\ell^2}. 
\end{equation}
\end{subequations}
\end{enumerate}
\end{lemma}

\begin{proof}
\ref{l:L-resol_only}: Let $(x,a), (y,b)\in \gra J_{\gamma A}$. Then $x =a+\gamma Aa$ and $y =b+\gamma Ab$. By Lipschitz continuity, $\|Aa-Ab\|\leq \ell\|a-b\|$. It follows that
\begin{equation}
\|x-y\|\leq \|a-b\| +\gamma\|Aa-Ab\|\leq (1+\gamma\ell)\|a-b\|
\end{equation}
and that
\begin{subequations}
\label{e:L-resol}
\begin{align}
2\scal{x-y}{a-b} &=\|x-y\|^2 +\|a-b\|^2 -\|(x-a)-(y-b)\|^2\\
&=\|x-y\|^2 +\|a-b\|^2 -\gamma^2\|Aa-Ab\|^2\\
&\geq \|x-y\|^2 +(1-\gamma^2\ell^2)\|a-b\|^2.
\end{align}
\end{subequations}
If $\gamma\ell\leq 1$, then combining the above inequalities yields
\begin{equation}
2\scal{x-y}{a-b}\geq \|x-y\|^2 +\frac{1-\gamma^2\ell^2}{(1+\gamma\ell)^2}\|x-y\|^2 =\frac{2}{1+\gamma\ell}\|x-y\|^2,
\end{equation}
and we get the claim.

\ref{l:L-resol_mono}: We first note that $J_{\gamma A}$ is single-valued due to Proposition~\ref{p:resol}\ref{p:resol_single}. Then \eqref{e:L-resol} reads as
\begin{equation}
\label{e:L-resol'}
2\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq \|x-y\|^2 +(1-\gamma^2\ell^2)\|J_{\gamma A}x-J_{\gamma A}y\|^2.
\end{equation}
We claim that if $\gamma\ell\geq 1$ or $A$ satisfies \eqref{e:alpha-mono} with equality, then 
\begin{equation}
\label{e:L-resol''}
2\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq \|x-y\|^2 +\frac{1-\gamma^2\ell^2}{1+\gamma\alpha}\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}.
\end{equation} 
Indeed, the former case implies $1-\gamma^2\ell^2\leq 0$ and, by combining \eqref{e:L-resol'} with Lemma~\ref{l:resol}\ref{l:resol_single} and noting that $1+\gamma\alpha >0$, we get \eqref{e:L-resol''}.  
In the latter case, Lemma~\ref{l:resol}\ref{l:resol_single} reduces to
\begin{equation}
\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y} =(1+\gamma\alpha)\|J_{\gamma A}x-J_{\gamma A}y\|^2.
\end{equation} 
Substituting this into \eqref{e:L-resol'}, we also obtain \eqref{e:L-resol''}. 

Now, in view of Remark~\ref{r:Lip_mono}, $1+2\gamma\alpha+\gamma^2\ell^2\geq 1+2\gamma\alpha+\gamma^2\alpha^2 =(1+\gamma\alpha)^2 >0$. It thus follows from \eqref{e:L-resol''} that 
\begin{equation}
\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq \frac{1+\gamma\alpha}{1+2\gamma\alpha+\gamma^2\ell^2}\|x-y\|^2.
\end{equation}
Finally, if $\gamma\ell\leq 1$, then, by \ref{l:L-resol_only}, 
\begin{equation}
\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq \frac{1}{1+\gamma\ell}\|x-y\|^2,
\end{equation}
and the conclusion follows.
\end{proof}

\begin{proposition}[linear combinations of resolvents and the identity]
\label{p:cresol}
Let $A\colon X\rightrightarrows X$ be $\alpha$-monotone and let $\gamma\in \RPP$. Set $J:=J_{\gamma A}$ and define $Q :=\nu\Id+\lambda J$ with $\nu, \lambda\in \RR$. 
\begin{enumerate}
\item\label{p:cresol_mono} 
Suppose that $J$ is single-valued and $\nu\lambda\leq 0$. Then, for all $x,y\in \dom J$, 
\begin{equation}
\|Qx-Qy\|^2\leq \nu^2\|x-y\|^2 +\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\|Jx-Jy\|^2.
\end{equation}
\item\label{p:cresol_Lip}
Suppose that $A$ is Lipschitz continuous with constant $\ell$, $1+\gamma\alpha >0$, and $\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\leq 0$. Then $Q$ is Lipschitz continuous with constant    
\begin{equation}
\label{e:LipQ}
\rho :=\sqrt{\nu^2+\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\alpha_J},
\end{equation}
where $\alpha_J$ is defined as \eqref{e:alpha_J}.
If additionally $\lambda\left(\nu+\frac{\lambda}{1-\gamma^2\ell^2}\right)\geq 0$ whenever $\gamma\ell <1$, then the Lipschitz constant \eqref{e:LipQ} can be improved to
\begin{equation}
\overline{\rho} :=\sqrt{\nu^2+\frac{\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)}{1+2\gamma\alpha+\gamma^2\ell^2}}\leq \rho.
\end{equation}
\end{enumerate}
\end{proposition}

\begin{proof}
Let $x,y\in \dom J$. By the definition of $Q$,
\begin{subequations}
\label{e:identityQ}
\begin{align}
\|Qx-Qy\|^2
&=\|\nu(x-y)+\lambda(Jx-Jy)\|^2\\
&=\nu^2\|x-y\|^2 +2\nu\lambda\scal{x-y}{Jx-Jy} +\lambda^2\|Jx-Jy\|^2.
\end{align}
\end{subequations}

\ref{p:cresol_mono}: Since $\nu\lambda\leq 0$, combining \eqref{e:identityQ} with Lemma~\ref{l:resol}\ref{l:resol_single} yields
\begin{subequations}
\begin{align}
\|Qx-Qy\|^2
&\leq \nu^2\|x-y\|^2 +2\nu\lambda(1+\gamma\alpha)\|Jx-Jy\|^2 +\lambda^2\|Jx-Jy\|^2\\
&=\nu^2\|x-y\|^2 +\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\|Jx-Jy\|^2.
\end{align}
\end{subequations}

\ref{p:cresol_Lip}: First, according to Proposition~\ref{p:resol}\ref{p:resol_single}, $J$ is single-valued, and so is $Q$. Next, using \eqref{e:identityQ}, Lemma~\ref{l:resol}\ref{l:resol_single}, and Lemma~\ref{l:L-resol}\ref{l:L-resol_mono} and noting that $\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\leq 0$, we have
\begin{subequations}
\label{e:cresol_Lip}
\begin{align}
\|Qx-Qy\|^2 
&\leq \nu^2\|x-y\|^2 +2\nu\lambda\scal{x-y}{Jx-Jy} +\frac{\lambda^2}{1+\gamma\alpha}\scal{x-y}{Jx-Jy}\\ 
&= \nu^2\|x-y\|^2 +\frac{\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)}{1+\gamma\alpha}\scal{x-y}{Jx-Jy}\\  
&\leq \nu^2\|x-y\|^2 +\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\alpha_J\|x-y\|^2 =\rho^2\|x-y\|^2, 
\end{align}
\end{subequations}
which implies that $Q$ is Lipschitz continuous with constant $\rho$.

For the last statement, we show that $\alpha_J$ in formula \eqref{e:LipQ} can be replaced by 
\begin{equation}
\overline{\alpha}_J :=\frac{1}{1+2\gamma\alpha+\gamma^2\ell^2}.
\end{equation}
If $\scal{x-y}{Jx-Jy}\geq (1+\gamma\alpha)\overline{\alpha}_J\|x-y\|^2$, then \eqref{e:cresol_Lip} also holds with $\alpha_J$ replaced by $\overline{\alpha}_J$. Now, assume that $\scal{x-y}{Jx-Jy} <(1+\gamma\alpha)\overline{\alpha}_J\|x-y\|^2$. By Lemma~\ref{l:L-resol}\ref{l:L-resol_mono}, we must have $\gamma\ell <1$, and then, by assumption, $\lambda\left(\nu+\frac{\lambda}{1-\gamma^2\ell^2}\right)\geq 0$. It now follows from \eqref{e:identityQ} and \eqref{e:L-resol_only} that
\begin{subequations}
\begin{align}
\|Qx-Qy\|^2
&\leq \nu^2\|x-y\|^2 +2\nu\lambda\scal{x-y}{Jx-Jy} \notag\\ 
&\qquad +\frac{\lambda^2}{1-\gamma^2\ell^2}(2\scal{x-y}{Jx-Jy} -\|x-y\|^2)\\
&=\Big(\nu^2-\frac{\lambda^2}{1-\gamma^2\ell^2}\Big)\|x-y\|^2 +2\lambda\Big(\nu+\frac{\lambda}{1-\gamma^2\ell^2}\Big)\scal{x-y}{Jx-Jy}\\
&\leq \Big(\nu^2-\frac{\lambda^2}{1-\gamma^2\ell^2}\Big)\|x-y\|^2 +2\lambda\Big(\nu+\frac{\lambda}{1-\gamma^2\ell^2}\Big)(1+\gamma\alpha)\overline{\alpha}_J\|x-y\|^2\\
&=\Big(\nu^2+\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\overline{\alpha}_J\Big)\|x-y\|^2 =\overline{\rho}^2\|x-y\|^2.
\end{align}
\end{subequations}
Finally, we will prove $\overline{\alpha}_J\geq \alpha_J$, which implies $\overline{\rho}\leq \rho$, i.e., the Lipschitz constant is indeed improved. From the definition of $\alpha_J$, it suffices to consider the case in which $\alpha_J =1/((1+\gamma\alpha)(1+\gamma\ell))$. Then $\gamma\ell\leq 1$. 
Since $|\alpha|\leq \ell$ (see Remark~\ref{r:Lip_mono}), it holds that
\begin{subequations}
\begin{align}
0 <(1+\gamma\alpha)^2\leq 1+2\gamma\alpha+\gamma^2\ell^2
&\leq 
1+2\gamma\alpha+\gamma^2\ell^2
+(\gamma\ell-\gamma\alpha)-\gamma\ell(\gamma\ell-\gamma\alpha)\\
&=1+\gamma\alpha+\gamma\ell+(\gamma\alpha)(\gamma\ell)\\
&=(1+\gamma\alpha)(1+\gamma\ell),
\end{align}
\end{subequations}
and so 
\begin{equation}
\overline{\alpha}_J =\frac{1}{1+2\gamma\alpha+\gamma^2\ell^2}\geq \alpha_J =\frac{1}{(1+\gamma\alpha)(1+\gamma\ell)}.
\end{equation}
The proof is complete.
\end{proof}

\begin{corollary}[relaxed resolvents of $\alpha$-monotone operators]
\label{c:rresol}
Let $A\colon X\rightrightarrows X$ be $\alpha$-monotone and let $\gamma\in \RPP$. Suppose that $J:=J_{\gamma A}$ is single-valued and define $R:=(1-\lambda)\Id +\lambda J$ with $\lambda\in \RP$, and $Q:=R+\varepsilon\Id$ with $\varepsilon\in \RR$. Then the following hold:
\begin{enumerate}
\item\label{c:rresol_relax} 
If $\lambda\geq 1$, then, for all $x, y\in \dom J$, 
\begin{equation}
\|Rx-Ry\|^2\leq (\lambda-1)^2\|x-y\|^2 -\lambda\big((\lambda-1)(2+2\gamma\alpha)-\lambda\big)\|Jx-Jy\|^2.
\end{equation}
\item\label{c:rresol_perturb} 
If $\varepsilon\leq \lambda-1$, then, for all $x, y\in \dom J$, 
\begin{align}
\|Qx-Qy\|^2 &\leq (\lambda-1-\varepsilon)^2\|x-y\|^2 \notag\\ 
&\quad -\lambda\big((\lambda-1)(2+2\gamma\alpha)-\lambda-2\varepsilon(1+\gamma\alpha)\big)\|Jx-Jy\|^2.
\end{align}
Consequently, if additionally $(\lambda-1)(2+2\gamma\alpha)-\lambda-2\varepsilon(1+\gamma\alpha)\geq 0$, then $Q$ is Lipschitz continuous with constant $(\lambda-1-\varepsilon)$.
\end{enumerate} 
\end{corollary}

\begin{proof}
Because \ref{c:rresol_relax} is a consequence of \ref{c:rresol_perturb} with $\varepsilon =0$, it suffices to prove only the latter. To this end, noting that $Q =R+\varepsilon\Id =(1-\lambda+\varepsilon)\Id+\lambda J$ and using Proposition~\ref{p:cresol}\ref{p:cresol_mono} with $\nu =1-\lambda+\varepsilon \leq 0$, we have that
\begin{subequations}
\begin{align}
\|Qx-Qy\|^2&\leq (1-\lambda+\varepsilon)^2\|x-y\|^2 +\lambda\left(2(1-\lambda+\varepsilon)(1+\gamma\alpha)+\lambda\right)\|Jx-Jy\|^2\\
&=(\lambda-1-\varepsilon)^2\|x-y\|^2 -\lambda\big((\lambda-1)(2+2\gamma\alpha)-\lambda-2\varepsilon(1+\gamma\alpha)\big)\|Jx-Jy\|^2
\end{align}
\end{subequations}
which proves \ref{c:rresol_perturb}. 
\end{proof}

\begin{corollary}[relaxed resolvents of Lipschitz $\alpha$-monotone operators]
\label{c:L-rresol}
Let $A\colon X\to X$ be $\alpha$-monotone and Lipschitz continuous with constant $\ell$. Also let $\gamma\in\RPP$ and $\lambda\in\RPP$ be such that
\begin{equation}\label{e:cL-rresol-1}
1+\gamma\alpha>0
\ \text{ and }\ 
\lambda(1+2\gamma\alpha)-2(1+\gamma\alpha)\geq 0.
\end{equation}
Define $J:=J_{\gamma A}$, $R:=(1-\lambda)\Id +\lambda J$, and $Q :=\Id-\varepsilon R$ with $\varepsilon\in \RP$. Then the following hold:
\begin{enumerate}
\item\label{c:L-rresol_relax} 
$R$ is Lipschitz continuous with constant 
\begin{equation}
\sqrt{(\lambda-1)^2-\frac{\lambda\big((\lambda-1)(2+2\gamma\alpha)-\lambda\big)}{1+2\gamma\alpha+\gamma^2\ell^2}}.
\end{equation} 
\item\label{c:L-rresol_perturb} 
$Q$ is Lipschitz continuous with constant 
\begin{equation}
\sqrt{(1+\varepsilon(\lambda-1))^2 -\varepsilon\lambda\Big[2(1+\gamma\alpha) +\varepsilon\big(\lambda(1+2\gamma\alpha)-2(1+\gamma\alpha)\big)\Big]\alpha_J},
\end{equation}
where $\alpha_J$ is defined as \eqref{e:alpha_J}.
\end{enumerate}
\end{corollary}

\begin{proof}
\ref{c:L-rresol_relax}: We observe that $R=\nu\Id+\lambda J$ with $\nu :=1-\lambda$, that
\begin{equation}
\lambda(2\nu(1+\gamma\alpha)+\lambda) =-\lambda\Big(\lambda(1+2\gamma\alpha)-2(1+\gamma\alpha)\Big)\leq 0,
\end{equation} 
and that, whenever $\gamma\ell <1$, 
\begin{equation}
\nu+\frac{\lambda}{1-\gamma^2\ell^2}=
(1-\lambda)+\frac{\lambda}{1-\gamma^2\ell^2} >1-\lambda+\lambda =1 >0.
\end{equation}
Applying Proposition~\ref{p:cresol}\ref{p:cresol_Lip} to $R=\nu\Id+\lambda\Id$ implies that $R$ is Lipschitz continuous with constant
\begin{equation}
\sqrt{(1-\lambda)^2+\frac{\lambda\big(2(1-\lambda)(1+\gamma\alpha)+\lambda\big)}{1+2\gamma\alpha+\gamma^2\ell^2}},
\end{equation} 
which gives the claim.

\ref{c:L-rresol_perturb}: Using the first part of Proposition~\ref{p:cresol}\ref{p:cresol_Lip} and writing $Q =\widetilde{\nu}\Id+\widetilde{\lambda}J$ with $\widetilde{\nu} :=1+\varepsilon(\lambda-1)$ and $\widetilde{\lambda} :=-\varepsilon\lambda$, it suffices to check that
\begin{equation}\label{e:cL-rresol-2}
\widetilde{\lambda}(2\widetilde{\nu}(1+\gamma\alpha)+\widetilde{\lambda})=(-\varepsilon\lambda)\big( 2(1+\varepsilon(\lambda-1))(1+\gamma\alpha)+(-\varepsilon\lambda) \big)\leq 0.
\end{equation}
Indeed, we have that $\varepsilon\geq 0$, $\lambda >0$, and  
\begin{subequations}
\begin{align}
2(1+\varepsilon(\lambda-1))(1+\gamma\alpha) -\varepsilon\lambda 
&=2(1+\gamma\alpha) +\varepsilon\big(2(\lambda-1)(1+\gamma\alpha)-\lambda\big)\\
&=2(1+\gamma\alpha) +\varepsilon(\lambda(1+2\gamma\alpha)-2(1+\gamma\alpha)) >0
\end{align}
\end{subequations}
by \eqref{e:cL-rresol-1}. So \eqref{e:cL-rresol-2} holds and the conclusion follows.
\end{proof}

\begin{lemma}[single-valuedness and full domain of adaptive DR operator]
\label{l:domT}
Suppose that $A$ and $B$ are maximally $\alpha$- and $\beta$-monotone with $\alpha+\beta\geq 0$. 
Then there exists $(\gamma,\delta,\lambda,\mu)\in \RPP^2\times \left]1,+\infty\right[^2$ such that
\begin{subequations}
\label{e:parameters}
\begin{align}
&1+2\gamma\alpha >0,
\label{e:parameters_a}\\
&\mu\in \left[2-2\gamma\beta, 2+2\gamma\alpha\right],
\label{e:parameters_b} \\
&(\lambda-1)(\mu-1) =1, \text{~and~} \delta =(\lambda-1)\gamma. \label{e:parameters_c}
\end{align}
\end{subequations}
Moreover, \eqref{e:parameters} implies that $\min\{1+\gamma\alpha, 1+\delta\beta\} >0$ and that $J_1$, $J_2$, and $T$ are single-valued and have full domain. 
\end{lemma}

\begin{proof}
To show the existence, we first take $\gamma>0$ such that $1/\gamma >-2\alpha$. Then $1+2\gamma\alpha >0$ and $2+2\gamma\alpha =1+(1+2\gamma\alpha) >1$.
Using $\alpha+\beta\geq 0$, we derive that
\begin{equation}
2+2\gamma\alpha =2\gamma(\alpha+\beta) +(2-2\gamma\beta)\geq 2-2\gamma\beta.
\end{equation}
Hence, we can always choose $\mu >1$ satisfying \eqref{e:parameters_b}. Next, with such $\mu$, we define $\lambda :=\mu/(\mu-1) =1+1/(\mu-1) >1$ and $\delta :=(\lambda-1)\gamma$. Then \eqref{e:parameters_c} is clearly satisfied. 

Now, take any $(\gamma,\delta,\lambda,\mu)$ satisfying \eqref{e:parameters}. We have
\begin{equation}
1+\delta\beta =(\lambda-1)(\mu-1)+(\lambda-1)\gamma\beta =\frac{1}{2}(\lambda-1)(\mu + \mu - (2-2\gamma\beta)) >0.
\end{equation}
Thus, $\min\{1+\gamma\alpha, 1+\delta\beta\} >0$. The remaining conclusion follows from Proposition~\ref{p:resol}. 
\end{proof}

\begin{proof}
In view of Remark~\ref{r:Lip_mono}, assumption \ref{t:linear_reduce} implies assumption \ref{t:linear_full} because if $A$ is Lipschitz continuous with constant $\ell$, then $A$ is also $\alpha$-monotone with $\alpha :=-\ell$. It thus suffices to assume \ref{t:linear_full}.  
First, Proposition~\ref{p:maxalpha}\ref{p:maxalpha_cont} implies that $A$ is maximally $\alpha$-monotone. Next, we learn from Lemma~\ref{l:domT} that 
\begin{equation}
\label{e:domT'}
\min\{1+\gamma\alpha,1+\delta\beta\} >0
\end{equation}
and that all operators $J_1,J_2$, and $T$ are single-valued and have full domain. 

By the choice of $\mu$, it holds that $0 <\mu-1 \leq 1+2\gamma\alpha$, and so
\begin{equation}
\lambda =1+\frac{1}{\mu-1}\geq 1+\frac{1}{1+2\gamma\alpha} =\frac{2(1+\gamma\alpha)}{1+2\gamma\alpha},
\end{equation} 
which yields
\begin{equation}
\lambda(1+2\gamma\alpha)-2(1+\gamma\alpha)\geq 0.
\end{equation}
From $\mu\geq 2-2\gamma\beta$, we have that $\varepsilon\geq 0$ and $\varepsilon_1\geq 0$. It follows that $\varphi\geq 0$ and that
\begin{equation}\label{e:180823a}
\varphi =0 \iff \varepsilon_1 =0 \iff \varepsilon =0 \iff \mu =2-2\gamma\beta.
\end{equation}
Define $Q_1 :=\Id -\varepsilon_1 R_1$. Using Corollary~\ref{c:L-rresol} and noting that $\lambda =\mu(\lambda-1)$, we derive that $R_1$ is Lipschitz continuous with constant  
\begin{equation}
\sqrt{(\lambda-1)^2-\frac{\lambda\big((\lambda-1)(2+2\gamma\alpha)-\lambda\big)}{1+2\gamma\alpha+\gamma^2\ell^2}} =(\lambda-1)\sqrt{1-\frac{\mu(2+2\gamma\alpha-\mu)}{1+2\gamma\alpha+\gamma^2\ell^2}},
\end{equation} 
and that $Q_1$ is Lipschitz continuous with constant 
\begin{equation}
\label{e:rho1}
\rho_1 :=\sqrt{(1+\varepsilon_1(\lambda-1))^2 -\varphi\alpha_J}\leq 1+\varepsilon_1(\lambda-1),
\end{equation}
where $\alpha_J$ is defined as in \eqref{e:alpha_J}. It follows from \eqref{e:180823a} that the inequality is strict whenever $\mu >2-2\gamma\beta$.

Next, define $Q_2 :=R_2+\varepsilon\Id$. 
Since $\gamma =(\mu-1)\delta$, we note that
\begin{equation}
\varepsilon =\frac{\mu-(2-2\gamma\beta)}{2(1+\delta\beta)} =\frac{(\mu-1)(2+2\delta\beta)-\mu}{2(1+\delta\beta)} <\mu-1,
\end{equation}
which also gives
\begin{equation}
(\mu-1)(2+2\delta\beta)-\mu-2\varepsilon(1+\delta\beta) =0.
\end{equation}
By Corollary~\ref{c:rresol}\ref{c:rresol_perturb}, $Q_2$ is Lipschitz continuous with constant $(\mu-1-\varepsilon)$. Combining with the Lipschitz continuity of $R_1$ and noting that $(\mu-1)(\lambda-1) =1$, we have that $Q_2R_1$ is Lipschitz continuous with constant
\begin{subequations}
\label{e:rho2}
\begin{align}
\rho_2
&:=(\mu-1-\varepsilon)(\lambda-1)\sqrt{1-\frac{\mu(2+2\gamma\alpha-\mu)}{1+2\gamma\alpha+\gamma^2\ell^2}}\\
&\phantom{:}=(1-\varepsilon(\lambda-1))\sqrt{1-\frac{\mu(2+2\gamma\alpha-\mu)}{1+2\gamma\alpha+\gamma^2\ell^2}}\\
&\phantom{:}\leq 1-\varepsilon(\lambda-1),
\end{align}
\end{subequations} 
where the inequality is strict whenever $\mu <2+2\gamma\alpha$.  

Now, we express
\begin{subequations}
\begin{align}
T&=(1-\kappa)\Id -(1-\kappa)\varepsilon_1R_1 + \kappa R_2R_1+\kappa\varepsilon R_1\\
&=(1-\kappa)(\Id-\varepsilon_1R_1)+\kappa(R_2+\varepsilon\Id)R_1\\
&=(1-\kappa)Q_1+\kappa Q_2R_1.
\end{align}
\end{subequations}
We note from $\alpha+\beta >0$ that $2+2\gamma\alpha >2-2\gamma\beta$, so at least one of two inequalities in \eqref{e:rho1} and \eqref{e:rho2} is strict.
Therefore, $T$ is Lipschitz continuous with constant
\begin{equation}
\rho :=(1-\kappa)\rho_1+\kappa \rho_2 <(1-\kappa)(1+\varepsilon_1(\lambda-1))+\kappa(1-\varepsilon(\lambda-1))=1,
\end{equation}
which completes the proof.
\end{proof}

