\begin{fact}
\label{f:Minty}
Let $A\colon X\rightrightarrows X$ be monotone and let $\gamma\in \RPP$. Then $\dom J_{\gamma A} =X$ if and only if $A$ is maximally monotone.
\end{fact}

\begin{proof}
By definition, $\dom J_{\gamma A} =\ran(\Id+\gamma A) :=(\Id+\gamma A)(X)$. Since $\gamma\in \RPP$, it holds that $\gamma A$ is monotone. According to Minty's theorem (see, e.g., \cite[Theorem~21.1]{BC17}), $\dom J_{\gamma A} =\ran(\Id+\gamma A) =X$ if and only if $\gamma A$ is maximally monotone. By \cite[Proposition~20.22]{BC17}, the latter occurs if and only if $A$ is maximally monotone. 
\end{proof}

\begin{lemma}[monotonicity versus $\alpha$-monotonicity]
\label{l:transfer}
Let $A\colon X\rightrightarrows X$ and let $\alpha, \beta\in \RR$. Then the following hold:
\begin{enumerate}
\item\label{l:transfer_mono} 
$A$ is $\alpha$-monotone if and only if $A-\beta\Id$ is $(\alpha-\beta)$-monotone.

\item\label{l:transfer_maxmono}
$A$ is maximally $\alpha$-monotone if and only if $A-\beta\Id$ is maximally $(\alpha-\beta)$-monotone. 
\end{enumerate}
Consequently, $A$ is (resp., maximally) $\alpha$-monotone if and only if $A-\alpha\Id$ is (resp., maximally) monotone.
\end{lemma}

\begin{proof}
\ref{l:transfer_mono}: We first have the equivalences
\begin{subequations}
\begin{align}
(x,u)\in \gra A &\iff (x,u-\beta x)\in \gra(A-\beta\Id), \\
(y,v)\in \gra A &\iff (y,v-\beta y)\in \gra(A-\beta\Id),
\end{align}
\end{subequations}
and
\begin{equation}
\scal{x-y}{u-v}\geq \alpha\|x-y\|^2 \iff \scal{x-y}{(u-\beta x)-(v-\beta y)}\geq (\alpha-\beta)\|x-y\|^2,
\end{equation}
from which the conclusion follows.

\ref{l:transfer_maxmono}: Assume that $A$ is maximally $\alpha$-monotone. By \ref{l:transfer_mono}, $A-\beta\Id$ is $(\alpha-\beta)$-monotone. Now, suppose that $A-\beta\Id$ is not maximally $(\alpha-\beta)$-monotone. Then there must exist $B'\colon X\rightrightarrows X$ such that $B'$ is $(\alpha-\beta)$-monotone and $\gra(A-\beta\Id)\subsetneq \gra B'$. It follows that $B :=B'+\beta\Id$ is $\alpha$-monotone due to \ref{l:transfer_mono} and that $\gra A\subsetneq \gra B$, which contradict the maximal $\alpha$-monotonicity of $A$. We deduce that if $A$ is maximally $\alpha$-monotone, then $A-\beta\Id$ is maximally $(\alpha-\beta)$-monotone. This also implies that if $A-\beta\Id$ is maximally $(\alpha-\beta)$-monotone, then $A =(A-\beta\Id)+\beta\Id$ is maximally $\alpha$-monotone, and we are done. 
\end{proof}

