which gives $\|x-y\|\geq (1+\gamma\alpha)\|a-b\|$ while noting that this is trivial when $a =b$.

\begin{proposition}[single-valuedness and full domain]
\label{p:resol}
Let $A\colon X\rightrightarrows X$ be $\alpha$-monotone and let $\gamma\in \RPP$ such that $1+\gamma\alpha >0$. Then the following hold:
\begin{enumerate}
\item\label{p:resol_single} 
$J_{\gamma A}$ is single-valued.

\item\label{p:resol_dom} 
$\dom J_{\gamma A} =X$ if and only if $A$ is maximally $\alpha$-monotone.
\end{enumerate}
\end{proposition}

\begin{proof}
\ref{p:resol_single}: This follows from Lemma~\ref{l:resol}\ref{l:resol_gen}.

\ref{p:resol_dom}: By Lemma~\ref{l:transfer}\ref{l:transfer_mono}, $A':=A-\alpha\Id$ is monotone.
Noting that $(\beta T)^{-1} =T^{-1}\circ \frac{1}{\beta}\Id$ for any operator $T$ and any $\beta\in \RR\smallsetminus\{0\}$, we have
\begin{subequations}
\begin{align}
J_{\gamma A}&=(\Id+\gamma A)^{-1}=\big((1+\gamma\alpha)\Id+\gamma(A-\alpha\Id)\big)^{-1}\\
&=\left(\Id+\frac{\gamma}{1+\gamma\alpha} A'\right)^{-1} \circ \left(\frac{1}{1+\gamma\alpha}\Id\right)\\
&=J_{\frac{\gamma}{1+\gamma\alpha}A'}\circ \left(\frac{1}{1+\gamma\alpha}\Id\right).
\end{align}
\end{subequations}
It follows that 
\begin{subequations}
\begin{align}
\dom J_{\gamma A} =X & \iff \dom J_{\frac{\gamma}{1+\gamma\alpha}A'} =X &&\\
& \iff \text{$A'$ is maximally monotone} &&\hspace*{-.8in}\text{(by Fact~\ref{f:Minty})} \\
& \iff \text{$A$ is maximally $\alpha$-monotone} &&\hspace*{-.8in}\text{(by Lemma~\ref{l:transfer}\ref{l:transfer_maxmono})}.
\end{align}
\end{subequations}
The proof is complete.
\end{proof}

\ref{p:resol_dom}: By Lemma~\ref{l:transfer}\ref{l:transfer_mono}, $A':=A-\alpha\Id$ is monotone.
Noting that $(\beta T)^{-1} =T^{-1}\circ \frac{1}{\beta}\Id$ for any operator $T$ and any $\beta\in \RR\smallsetminus\{0\}$, we have
\begin{subequations}
\begin{align}
J_{\gamma A}&=(\Id+\gamma A)^{-1}=\big((1+\gamma\alpha)\Id+\gamma(A-\alpha\Id)\big)^{-1}\\
&=\left(\Id+\frac{\gamma}{1+\gamma\alpha} A'\right)^{-1} \circ \left(\frac{1}{1+\gamma\alpha}\Id\right)\\
&=J_{\frac{\gamma}{1+\gamma\alpha}A'}\circ \left(\frac{1}{1+\gamma\alpha}\Id\right).
\end{align}
\end{subequations}
It follows that 
\begin{subequations}
\begin{align}
\dom J_{\gamma A} =X & \iff \dom J_{\frac{\gamma}{1+\gamma\alpha}A'} =X &&\\
& \iff \text{$A'$ is maximally monotone} &&\hspace*{-.8in}\text{(by Fact~\ref{f:Minty})} \\
& \iff \text{$A$ is maximally $\alpha$-monotone} &&\hspace*{-.8in}\text{(by Lemma~\ref{l:transfer}\ref{l:transfer_maxmono})}.
\end{align}
\end{subequations}
The proof is complete.
\end{proof}

\begin{proposition}[maximal $\alpha$-monotonicity]
\label{p:maxalpha}
The following statements hold: 
\begin{enumerate}
\item\label{p:maxalpha_mono} 
Let $A\colon X\rightrightarrows X$ and $\alpha\in \RP$. Then $A$ is maximally $\alpha$-monotone if and only if $A$ is $\alpha$-monotone and maximally monotone.

\item\label{p:maxalpha_cont} 
Let $A\colon X\to X$ and $\alpha\in \RR$. Then $A$ is maximally $\alpha$-monotone if $A$ is $\alpha$-monotone and continuous with full domain.
\end{enumerate}
\end{proposition}

\begin{proof}
\ref{p:maxalpha_mono}: Since $\alpha\geq 0$, it follows from Fact~\ref{f:Minty} that $A$ is $\alpha$-monotone and maximally monotone if and only if $A$ is $\alpha$-monotone and $\dom J_A =X$, which, by Proposition~\ref{p:resol}\ref{p:resol_dom}, happen if and only if $A$ is maximally $\alpha$-monotone.

\ref{p:maxalpha_cont}: Set $A' :=A-\alpha\Id$. Then $A'$ is monotone (due to Lemma~\ref{l:transfer}\ref{l:transfer_mono}) and continuous with full domain. By \cite[Corollary~20.28]{BC17}, $A'$ is maximally monotone, and by Lemma~\ref{l:transfer}\ref{l:transfer_maxmono}, $A$ is maximally $\alpha$-monotone. 
\end{proof}

\begin{lemma}[resolvents of Lipschitz $\alpha$-monotone operators]
\label{l:L-resol}
Let $A\colon X\to X$ be Lipschitz continuous with constant $\ell$ and let $\gamma\in \RPP$. Then the following hold:
\begin{enumerate}
\item\label{l:L-resol_only} 
For all $(x,a), (y,b)\in \gra J_{\gamma A}$,
\begin{subequations}
\begin{align}
\label{e:expan}
\|a-b\|&\geq \frac{1}{1+\gamma\ell}\|x-y\|,\\
\label{e:L-resol_only}
\scal{x-y}{a-b}&\geq \frac{1}{2}\|x-y\|^2 +\frac{1}{2}(1-\gamma^2\ell^2)\|a-b\|^2,
\end{align}
\end{subequations}
and if $\gamma\ell\leq 1$, then
\begin{equation}\label{e:L-resol_only1}
\scal{x-y}{a-b}\geq \frac{1}{1+\gamma\ell}\|x-y\|^2.
\end{equation}

\item\label{l:L-resol_mono}
If $A$ is $\alpha$-monotone with $1+\gamma\alpha >0$, then, for all $x, y\in \dom J_{\gamma A}$, 
\begin{equation}
\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq (1+\gamma\alpha)\alpha_J\|x-y\|^2,
\end{equation}
where 
\begin{subequations}
\label{e:alpha_J}
\begin{equation}
\alpha_J 
:=\begin{cases}
\dfrac{1}{1+2\gamma\alpha+\gamma^2\ell^2} &\text{if~} \gamma\ell\geq 1 
,\\
\dfrac{1}{(1+\gamma\alpha)(1+\gamma\ell)} &\text{if~} \gamma\ell\leq 1;
\end{cases}
\end{equation}
and if additionally $A$ satisfies \eqref{e:alpha-mono} with equality, then 
\begin{equation}
\alpha_J :=\frac{1}{1+2\gamma\alpha+\gamma^2\ell^2}. 
\end{equation}
\end{subequations}
\end{enumerate}
\end{lemma}

