\begin{subequations}
\label{e:alpha_J}
\begin{equation}
\alpha_J 
:=\begin{cases}
\dfrac{1}{1+2\gamma\alpha+\gamma^2\ell^2} &\text{if~} \gamma\ell\geq 1 
,\\
\dfrac{1}{(1+\gamma\alpha)(1+\gamma\ell)} &\text{if~} \gamma\ell\leq 1;
\end{cases}
\end{equation}
and if additionally $A$ satisfies \eqref{e:alpha-mono} with equality, then 
\begin{equation}
\alpha_J :=\frac{1}{1+2\gamma\alpha+\gamma^2\ell^2}. 
\end{equation}
\end{subequations}

\begin{proof}
\ref{l:L-resol_only}: Let $(x,a), (y,b)\in \gra J_{\gamma A}$. Then $x =a+\gamma Aa$ and $y =b+\gamma Ab$. By Lipschitz continuity, $\|Aa-Ab\|\leq \ell\|a-b\|$. It follows that
\begin{equation}
\|x-y\|\leq \|a-b\| +\gamma\|Aa-Ab\|\leq (1+\gamma\ell)\|a-b\|
\end{equation}
and that
\begin{subequations}
\label{e:L-resol}
\begin{align}
2\scal{x-y}{a-b} &=\|x-y\|^2 +\|a-b\|^2 -\|(x-a)-(y-b)\|^2\\
&=\|x-y\|^2 +\|a-b\|^2 -\gamma^2\|Aa-Ab\|^2\\
&\geq \|x-y\|^2 +(1-\gamma^2\ell^2)\|a-b\|^2.
\end{align}
\end{subequations}
If $\gamma\ell\leq 1$, then combining the above inequalities yields
\begin{equation}
2\scal{x-y}{a-b}\geq \|x-y\|^2 +\frac{1-\gamma^2\ell^2}{(1+\gamma\ell)^2}\|x-y\|^2 =\frac{2}{1+\gamma\ell}\|x-y\|^2,
\end{equation}
and we get the claim.

\ref{l:L-resol_mono}: We first note that $J_{\gamma A}$ is single-valued due to Proposition~\ref{p:resol}\ref{p:resol_single}. Then \eqref{e:L-resol} reads as
\begin{equation}
\label{e:L-resol'}
2\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq \|x-y\|^2 +(1-\gamma^2\ell^2)\|J_{\gamma A}x-J_{\gamma A}y\|^2.
\end{equation}
We claim that if $\gamma\ell\geq 1$ or $A$ satisfies \eqref{e:alpha-mono} with equality, then 
\begin{equation}
\label{e:L-resol''}
2\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq \|x-y\|^2 +\frac{1-\gamma^2\ell^2}{1+\gamma\alpha}\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}.
\end{equation} 
Indeed, the former case implies $1-\gamma^2\ell^2\leq 0$ and, by combining \eqref{e:L-resol'} with Lemma~\ref{l:resol}\ref{l:resol_single} and noting that $1+\gamma\alpha >0$, we get \eqref{e:L-resol''}.  
In the latter case, Lemma~\ref{l:resol}\ref{l:resol_single} reduces to
\begin{equation}
\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y} =(1+\gamma\alpha)\|J_{\gamma A}x-J_{\gamma A}y\|^2.
\end{equation} 
Substituting this into \eqref{e:L-resol'}, we also obtain \eqref{e:L-resol''}. 

Now, in view of Remark~\ref{r:Lip_mono}, $1+2\gamma\alpha+\gamma^2\ell^2\geq 1+2\gamma\alpha+\gamma^2\alpha^2 =(1+\gamma\alpha)^2 >0$. It thus follows from \eqref{e:L-resol''} that 
\begin{equation}
\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq \frac{1+\gamma\alpha}{1+2\gamma\alpha+\gamma^2\ell^2}\|x-y\|^2.
\end{equation}
Finally, if $\gamma\ell\leq 1$, then, by \ref{l:L-resol_only}, 
\begin{equation}
\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq \frac{1}{1+\gamma\ell}\|x-y\|^2,
\end{equation}
and the conclusion follows.
\end{proof}

