\begin{proposition}[linear combinations of resolvents and the identity]
\label{p:cresol}
Let $A\colon X\rightrightarrows X$ be $\alpha$-monotone and let $\gamma\in \RPP$. Set $J:=J_{\gamma A}$ and define $Q :=\nu\Id+\lambda J$ with $\nu, \lambda\in \RR$. 
\begin{enumerate}
\item\label{p:cresol_mono} 
Suppose that $J$ is single-valued and $\nu\lambda\leq 0$. Then, for all $x,y\in \dom J$, 
\begin{equation}
\|Qx-Qy\|^2\leq \nu^2\|x-y\|^2 +\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\|Jx-Jy\|^2.
\end{equation}

\item\label{p:cresol_Lip}
Suppose that $A$ is Lipschitz continuous with constant $\ell$, $1+\gamma\alpha >0$, and $\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\leq 0$. Then $Q$ is Lipschitz continuous with constant    
\begin{equation}
\label{e:LipQ}
\rho :=\sqrt{\nu^2+\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\alpha_J},
\end{equation}
where $\alpha_J$ is defined as \eqref{e:alpha_J}.
If additionally $\lambda\left(\nu+\frac{\lambda}{1-\gamma^2\ell^2}\right)\geq 0$ whenever $\gamma\ell <1$, then the Lipschitz constant \eqref{e:LipQ} can be improved to
\begin{equation}
\overline{\rho} :=\sqrt{\nu^2+\frac{\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)}{1+2\gamma\alpha+\gamma^2\ell^2}}\leq \rho.
\end{equation}
\end{enumerate}
\end{proposition}

\begin{proof}
Let $x,y\in \dom J$. By the definition of $Q$,
\begin{subequations}
\label{e:identityQ}
\begin{align}
\|Qx-Qy\|^2
&=\|\nu(x-y)+\lambda(Jx-Jy)\|^2\\
&=\nu^2\|x-y\|^2 +2\nu\lambda\scal{x-y}{Jx-Jy} +\lambda^2\|Jx-Jy\|^2.
\end{align}
\end{subequations}

\ref{p:cresol_mono}: Since $\nu\lambda\leq 0$, combining \eqref{e:identityQ} with Lemma~\ref{l:resol}\ref{l:resol_single} yields
\begin{subequations}
\begin{align}
\|Qx-Qy\|^2
&\leq \nu^2\|x-y\|^2 +2\nu\lambda(1+\gamma\alpha)\|Jx-Jy\|^2 +\lambda^2\|Jx-Jy\|^2\\
&=\nu^2\|x-y\|^2 +\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\|Jx-Jy\|^2.
\end{align}
\end{subequations}

\ref{p:cresol_Lip}: First, according to Proposition~\ref{p:resol}\ref{p:resol_single}, $J$ is single-valued, and so is $Q$. Next, using \eqref{e:identityQ}, Lemma~\ref{l:resol}\ref{l:resol_single}, and Lemma~\ref{l:L-resol}\ref{l:L-resol_mono} and noting that $\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\leq 0$, we have
\begin{subequations}
\label{e:cresol_Lip}
\begin{align}
\|Qx-Qy\|^2 
&\leq \nu^2\|x-y\|^2 +2\nu\lambda\scal{x-y}{Jx-Jy} +\frac{\lambda^2}{1+\gamma\alpha}\scal{x-y}{Jx-Jy}\\ 
&= \nu^2\|x-y\|^2 +\frac{\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)}{1+\gamma\alpha}\scal{x-y}{Jx-Jy}\\  
&\leq \nu^2\|x-y\|^2 +\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\alpha_J\|x-y\|^2 =\rho^2\|x-y\|^2, 
\end{align}
\end{subequations}
which implies that $Q$ is Lipschitz continuous with constant $\rho$.

For the last statement, we show that $\alpha_J$ in formula \eqref{e:LipQ} can be replaced by 
\begin{equation}
\overline{\alpha}_J :=\frac{1}{1+2\gamma\alpha+\gamma^2\ell^2}.
\end{equation}
If $\scal{x-y}{Jx-Jy}\geq (1+\gamma\alpha)\overline{\alpha}_J\|x-y\|^2$, then \eqref{e:cresol_Lip} also holds with $\alpha_J$ replaced by $\overline{\alpha}_J$. Now, assume that $\scal{x-y}{Jx-Jy} <(1+\gamma\alpha)\overline{\alpha}_J\|x-y\|^2$. By Lemma~\ref{l:L-resol}\ref{l:L-resol_mono}, we must have $\gamma\ell <1$, and then, by assumption, $\lambda\left(\nu+\frac{\lambda}{1-\gamma^2\ell^2}\right)\geq 0$. It now follows from \eqref{e:identityQ} and \eqref{e:L-resol_only} that
\begin{subequations}
\begin{align}
\|Qx-Qy\|^2
&\leq \nu^2\|x-y\|^2 +2\nu\lambda\scal{x-y}{Jx-Jy} \notag\\ 
&\qquad +\frac{\lambda^2}{1-\gamma^2\ell^2}(2\scal{x-y}{Jx-Jy} -\|x-y\|^2)\\
&=\Big(\nu^2-\frac{\lambda^2}{1-\gamma^2\ell^2}\Big)\|x-y\|^2 +2\lambda\Big(\nu+\frac{\lambda}{1-\gamma^2\ell^2}\Big)\scal{x-y}{Jx-Jy}\\
&\leq \Big(\nu^2-\frac{\lambda^2}{1-\gamma^2\ell^2}\Big)\|x-y\|^2 +2\lambda\Big(\nu+\frac{\lambda}{1-\gamma^2\ell^2}\Big)(1+\gamma\alpha)\overline{\alpha}_J\|x-y\|^2\\
&=\Big(\nu^2+\lambda\big(2\nu(1+\gamma\alpha)+\lambda\big)\overline{\alpha}_J\Big)\|x-y\|^2 =\overline{\rho}^2\|x-y\|^2.
\end{align}
\end{subequations}
Finally, we will prove $\overline{\alpha}_J\geq \alpha_J$, which implies $\overline{\rho}\leq \rho$, i.e., the Lipschitz constant is indeed improved. From the definition of $\alpha_J$, it suffices to consider the case in which $\alpha_J =1/((1+\gamma\alpha)(1+\gamma\ell))$. Then $\gamma\ell\leq 1$. 
Since $|\alpha|\leq \ell$ (see Remark~\ref{r:Lip_mono}), it holds that
\begin{subequations}
\begin{align}
0 <(1+\gamma\alpha)^2\leq 1+2\gamma\alpha+\gamma^2\ell^2
&\leq 
1+2\gamma\alpha+\gamma^2\ell^2
+(\gamma\ell-\gamma\alpha)-\gamma\ell(\gamma\ell-\gamma\alpha)\\
&=1+\gamma\alpha+\gamma\ell+(\gamma\alpha)(\gamma\ell)\\
&=(1+\gamma\alpha)(1+\gamma\ell),
\end{align}
\end{subequations}
and so 
\begin{equation}
\overline{\alpha}_J =\frac{1}{1+2\gamma\alpha+\gamma^2\ell^2}\geq \alpha_J =\frac{1}{(1+\gamma\alpha)(1+\gamma\ell)}.
\end{equation}
The proof is complete.
\end{proof}

