We say that $A$ is \emph{Lipschitz continuous} with constant $\ell\in \RP$ if it is single-valued and
\begin{equation}
\forall x, y\in \dom A,\quad \|Ax-Ay\|\leq \ell\|x-y\|.
\end{equation}
The operator $A$ is \emph{nonexpansive} if it is Lipschitz continuous with constant $1$, i.e.,
\begin{equation}
\forall x, y\in \dom A,\quad \|Ax-Ay\|\leq \|x-y\|.
\end{equation}

An operator $A\colon X\rightrightarrows X$ is said to be \emph{monotone} if
\begin{equation}
\forall (x, u), (y, v)\in \gra A,\quad \scal{x-y}{u-v}\geq 0,
\end{equation}
and said to be \emph{maximally monotone} if it is monotone and there exists no monotone operator $B\colon X\rightrightarrows X$ such that $\gra B$ properly contains $\gra A$. The \emph{resolvent} of $A\colon X\rightrightarrows X$ is defined by

and said to be \emph{maximally monotone} if it is monotone and there exists no monotone operator $B\colon X\rightrightarrows X$ such that $\gra B$ properly contains $\gra A$. The \emph{resolvent} of $A\colon X\rightrightarrows X$ is defined by
\begin{equation}
J_A:= (\Id+ A)^{-1},
\end{equation}
where $\Id$ is the identity operator. The \emph{relaxed resolvent} of $A$ with parameter $\lambda\in\RP$ is defined by
\begin{equation}
J_A^\lambda:= (1-\lambda)\Id+ \lambda J_A.
\end{equation}

\begin{definition}[$\alpha$-monotonicity]
\label{d:alpha_mono}
An operator $A\colon X\rightrightarrows X$ is said to be \emph{$\alpha$-monotone} ($\alpha\in \RR$) if
\begin{equation}
\label{e:alpha-mono}
\forall (x,u), (y,v)\in \gra A,\quad \scal{x-y}{u-v}\geq \alpha\|x-y\|^2.
\end{equation}
The constant $\alpha$ is referred to as the \emph{monotonicity constant}.
We also say that $A$ is \emph{maximally $\alpha$-monotone} if it is $\alpha$-monotone and there is no $\alpha$-monotone operator whose graph strictly contains $\gra A$.  
\end{definition}

\begin{remark}[Lipschitz $\alpha$-monotone operators]
\label{r:Lip_mono}
