\begin{lemma}[resolvents of $\alpha$-monotone operators]
\label{l:resol}
Let $A\colon X\rightrightarrows X$ be $\alpha$-monotone and let $\gamma\in \RPP$. Then the following hold:
\begin{enumerate}
\item\label{l:resol_gen}
For all $(x,a), (y,b)\in \gra J_{\gamma A}$,
\begin{subequations}
\begin{align}
\label{e:resol_gen}
\scal{x-y}{a-b} &\geq (1+\gamma\alpha)\|a-b\|^2 \quad\text{and}\\
\|x-y\| &\geq (1+\gamma\alpha)\|a-b\|.
\end{align} 
\end{subequations}

\item\label{l:resol_single}
If $J_{\gamma A}$ is single-valued, then, for all $x,y\in \dom J_{\gamma A}$,
\begin{equation}
\scal{x-y}{J_{\gamma A}x-J_{\gamma A}y}\geq (1+\gamma\alpha)\|J_{\gamma A}x-J_{\gamma A}y\|^2,
\end{equation}
i.e., $J_{\gamma A}$ is $(1+\gamma\alpha)$-cocoercive.
\end{enumerate}
\end{lemma}

\begin{proof}
\ref{l:resol_gen}: Let $(x,a), (y,b)\in \gra J_{\gamma A}$. Then $x\in (\Id+\gamma A)a$, $y\in (\Id+\gamma A)b$, and so $x =a+\gamma u$, $y =b+\gamma v$ for some $u\in Aa$, $v\in Ab$. We derive from the $\alpha$-monotonicity of $A$ that 
\begin{subequations}
\begin{align}
\scal{x-y}{a-b}
&=\scal{(a+\gamma u)-(b+\gamma v)}{a-b}\\
&=\|a-b\|^2+\gamma\scal{a-b}{u-v}\\
&\geq \|a-b\|^2+\gamma\alpha\|a-b\|^2\\
&=(1+\gamma\alpha)\|a-b\|^2.
\end{align}
\end{subequations}
Now, by the Cauchy--Schwarz inequality,
\begin{equation}
\|x-y\|\|a-b\|\geq \scal{x-y}{a-b}\geq (1+\gamma\alpha)\|a-b\|^2.
\end{equation}
which gives $\|x-y\|\geq (1+\gamma\alpha)\|a-b\|$ while noting that this is trivial when $a =b$. 

\ref{l:resol_single}: This is a direct consequence of \ref{l:resol_gen}.
\end{proof}

